}
```


Fixes #90583

issue_context.body:
### Description

Desired balance (and metrics calculated in https://github.com/elastic/elasticsearch/issues/90582) should be exposed via experimental endpoint.

We might use `GET /_internal/desired_balance` for now that will return something like:

```
{
 "stats": {
    "last_converged_index":n,
    "computation_active":true/false,
    "undesired_allocation_count":n,
    "unassigned_shard_count":n,
    "total_shard_count":n,
    "computation_started_count":n,
    "computation_converged_count":n,
    "cumulative_computation_time":"100ms",
    "cumulative_computation_time_in_millis":100,
    "cumulative_reconciliation_time":"100ms",
    "cumulative_reconciliation_time_in_millis":100
  },
  "routing_table": {
    "my-index": {
      "0": {
      "current":[
        {
          "state": "STARTED",
          "primary": true,
          "node": "khrEQSSURmeJicTuLsP0YA",
          "node_is_desired": true,
          "relocating_node": null,
          "relocating_node_is_desired": null,
          "shard": 0,
          "index": "my-index",
          "allocation_id": {
            "id": "OxJQIH-NRlS36DG9Aark0Q"
          }
        }
      ],
      "desired":{
        "nodes":[...],
        "total":n,
        "unassigned":n,
        "ignored"
        }
      }
    }
  },
...
```

Later this api should be split into balance and stats and replaced with a permanent APIs.
